import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.DgsHl6ax.js";const p=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),o={name:"explanation/decisions.md"};function r(n,e,c,l,d,m){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: the load-bearing decisions, each with the alternative it beat and the consequence it carries. Design history lives in the <code>project/</code> myco ledger.</p><h2 id="the-wal-is-the-state" tabindex="-1">The WAL is the state <a class="header-anchor" href="#the-wal-is-the-state" aria-label="Permalink to &quot;The WAL is the state&quot;">​</a></h2><p><strong>Decision:</strong> ops live in <code>refs/sturn/wal/*</code> as ordinary git objects; the bus, cursors, and materialized views are caches.</p><ul><li><em>Alternative:</em> a dedicated database (or the bus) as authority.</li><li><em>Consequence:</em> replication is plain <code>git push</code>/<code>fetch</code> — signed by git&#39;s machinery, no new sync protocol. Cost: everything reconstructible must <em>stay</em> reconstructible; the rule is enforced by review.</li></ul><h2 id="ops-are-metadata-merges-stay-git-s" tabindex="-1">Ops are metadata; merges stay git&#39;s <a class="header-anchor" href="#ops-are-metadata-merges-stay-git-s" aria-label="Permalink to &quot;Ops are metadata; merges stay git&#39;s&quot;">​</a></h2><p><strong>Decision:</strong> coordination ops never encode merge semantics — claims prevent collisions, <code>snap</code> produces ordinary commits.</p><ul><li><em>Alternative:</em> CRDT merge for the tree, or a custom merge driver.</li><li><em>Consequence:</em> see <a href="./no-crdt.html">Why no CRDT for code</a> — the log converges deterministically, the tree needs decisions, and claims make most collisions never happen.</li></ul><h2 id="workspaces-are-pointers" tabindex="-1">Workspaces are pointers <a class="header-anchor" href="#workspaces-are-pointers" aria-label="Permalink to &quot;Workspaces are pointers&quot;">​</a></h2><p><strong>Decision:</strong> <code>refs/sturn/ws/&lt;name&gt;</code> is a ref, not a checkout — a thousand agent workspaces cost nothing.</p><ul><li><em>Alternative:</em> git worktrees or clones per agent.</li><li><em>Consequence:</em> parallelism scales to the ref namespace; real files materialize only on demand (hydrate/exec/mount) for the tools that genuinely need POSIX.</li></ul><h2 id="claims-before-edits" tabindex="-1">Claims before edits <a class="header-anchor" href="#claims-before-edits" aria-label="Permalink to &quot;Claims before edits&quot;">​</a></h2><p><strong>Decision:</strong> advisory locks publish <em>before</em> work starts — coordination precedes the edit, not the merge.</p><ul><li><em>Alternative:</em> detect conflicts at merge/snap time.</li><li><em>Consequence:</em> contenders learn in milliseconds and pick different resources; the failure mode git taught us (discovering the collision at a three-way merge) is designed out.</li></ul><h2 id="continuous-review-over-the-pr-gate" tabindex="-1">Continuous review over the PR gate <a class="header-anchor" href="#continuous-review-over-the-pr-gate" aria-label="Permalink to &quot;Continuous review over the PR gate&quot;">​</a></h2><p><strong>Decision:</strong> every op streams through the WAL and can carry a <code>review</code> verdict; <code>[review] require</code> gates <code>snap</code> per-op.</p><ul><li><em>Alternative:</em> one big diff reviewed at PR time.</li><li><em>Consequence:</em> verdicts land <em>before</em> commit time, per op, from any actor (agents review agents); PRs become packaging, not the gate.</li></ul>',17)])])}const u=t(o,[["render",r]]);export{p as __pageData,u as default};
